yment reference" maxlength="80" required><button class="rounded-full bg-forest px-5 py-2 text-sm text-white">Submit reference</button></form><?php endif; ?></div><?php elseif($order['payment_method']==='mpesa'&&current_user()): ?><form data-ajax-form action="<?= e(url('payment/mpesa.php')) ?>" method="post" class="mt-5 grid gap-3 rounded bg-[#f4f0e9] p-4 sm:grid-cols-[1fr_auto]"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="order_id" value="<?= (int)$order['id'] ?>"><label class="text-sm">M-Pesa phone number<input class="form-control mt-1" name="phone" type="tel" placeholder="07XX XXX XXX" required></label><button class="self-end rounded-full bg-forest px-5 py-3 text-sm text-white">Request STK push</button></form><?php endif; ?></div><div class="mt-6 text-center"><a class="rounded-full bg-forest px-6 py-3 text-sm font-semibold text-white" href="<?= e(url(current_user()?'account/orders.php':'shop.php')) ?>"><?= current_user()?'View my orders':'Continue shopping' ?></a></div></section>
